use std::cmp::Ordering;
use std::ops::{Add, Mul, Sub};

/// Type implementing arbitrary-precision decimal arithmetic.
///
/// A `Decimal` stores its value as a sign, a sequence of decimal digits
/// (most significant first) representing the absolute value, and a scale —
/// the number of digits after the decimal point. The value is
/// `sign * digits / 10^scale`. Zero is normalized to have no digits and
/// a scale of 0, so there is no negative zero.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Decimal {
    sign: i8,
    digits: Vec<u8>,
    scale: usize,
}

impl Decimal {
    /// Create a new decimal from a string like `"123.45"`, `"-0.01"`, or `"+7"`.
    /// Returns `None` if the input is not a valid decimal literal.
    pub fn try_from(input: &str) -> Option<Decimal> {
        let (sign, rest) = if let Some(rest) = input.strip_prefix('+') {
            (1, rest)
        } else if let Some(rest) = input.strip_prefix('-') {
            (-1, rest)
        } else {
            (1, input)
        };

        let (int_part, frac_part) = match rest.find('.') {
            Some(i) => (&rest[..i], &rest[i + 1..]),
            None => (rest, ""),
        };
        if int_part.is_empty() && frac_part.is_empty() {
            return None;
        }

        let scale = frac_part.len();
        let mut digits: Vec<u8> = Vec::with_capacity(int_part.len() + frac_part.len());
        for c in int_part.chars().chain(frac_part.chars()) {
            if !c.is_ascii_digit() {
                return None;
            }
            digits.push(c as u8 - b'0');
        }

        // Strip leading zeros; a value of zero has no digits and scale 0.
        let first = digits.iter().position(|&d| d != 0)?;
        digits.drain(..first);
        Some(Decimal { sign, digits, scale })
    }
    ...
}
